const trial = $json;

// Beta studios never get trial nurture emails
if (trial.is_beta === true) {
  return {
    json: {
      ...trial,
      trial_day: 0,
      email_to_send: null,
      template_key: null,
      should_send: false
    }
  };
}

const startDate = new Date(trial.trial_start_date);
const now = new Date();

// Reset time to midnight for accurate day calculation
startDate.setHours(0, 0, 0, 0);
now.setHours(0, 0, 0, 0);

const diffTime = now - startDate;
const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

let emailToSend = null;
let templateKey = null;
let shouldSend = false;

const isActive = trial.has_generated_content === true;

// Day 1: Only if inactive (this is actually day after signup)
if (diffDays === 1 && !trial.day1_email_sent && !isActive) {
  templateKey = 'day1_inactive';
  emailToSend = 'day1';
  shouldSend = true;
}
// Day 3: Only if inactive
else if (diffDays === 3 && !trial.day3_email_sent && !isActive) {
  templateKey = 'day3_value';
  emailToSend = 'day3';
  shouldSend = true;
}
// Day 5: Only if inactive
else if (diffDays === 5 && !trial.day5_email_sent && !isActive) {
  templateKey = 'day5_feedback';
  emailToSend = 'day5';
  shouldSend = true;
}
// Day 6: Everyone gets reminder
else if (diffDays === 6 && !trial.day6_email_sent) {
  templateKey = isActive ? 'day6_active' : 'day6_inactive';
  emailToSend = 'day6';
  shouldSend = true;
}
// Day 7: Trial expired - final notice
else if (diffDays === 7 && !trial.day7_email_sent) {
  templateKey = 'day7_final';
  emailToSend = 'day7';
  shouldSend = true;
}
// Day 8: Winback - only if not converted
else if (diffDays === 8 && !trial.day8_email_sent && !trial.converted) {
  templateKey = 'day8_winback';
  emailToSend = 'day8';
  shouldSend = true;
}

return {
  json: {
    ...trial,
    trial_day: diffDays,
    email_to_send: emailToSend,
    template_key: templateKey,
    should_send: shouldSend
  }
};

const trial = $('Should Send Email?').item.json;
const templates = $input.all().map(i => i.json);
const template = templates[0];

if (!template) {
  return [{ json: { skip: true, reason: 'Template not found' } }];
}

const upgradeLink = 'https://app.fiorsaoirse.com/upgrade';
const loomLink = 'https://www.loom.com/share/YOUR_LOOM_ID';
const dashboardLink = 'https://app.fiorsaoirse.com/dashboard';

// Fetch brand_color from studio_accounts via Supabase REST.
// Falls back to FCA default (#6366F1) if no studio, no key, or fetch error.
let brandColor = '#6366F1';
try {
  const supaUrl = 'https://kidgcrqxrfcbsaeguwop.supabase.co';
  const supaKey = $vars.FCA_SUPABASE_SERVICE_KEY;
  if (supaKey && trial.email) {
    const res = await fetch(
      supaUrl + '/rest/v1/studio_accounts?select=brand_color&owner_email=eq.' + encodeURIComponent(trial.email),
      { headers: { 'apikey': supaKey, 'Authorization': 'Bearer ' + supaKey } }
    );
    const rows = await res.json();
    if (Array.isArray(rows) && rows[0] && rows[0].brand_color) {
      brandColor = rows[0].brand_color;
    }
  }
} catch (e) {
  // Silent fallthrough to FCA default
}
const unsubscribeUrl = 'mailto:admin@fiorsaoirse.com?subject=Unsubscribe';

let subject = template.subject || '';
let body = template.body_html || template.body_text || '';

// Replace all placeholders
const replacements = {
  '{{first_name}}': trial.first_name || 'there',
  '{{content_count}}': String(trial.content_count || 0),
  '{{brand_color}}': brandColor,
  '{{unsubscribe_url}}': unsubscribeUrl,
  '[UPGRADE_LINK]': upgradeLink,
  '[LOOM_LINK]': loomLink,
  '[DASHBOARD_LINK]': dashboardLink
};

for (const [placeholder, value] of Object.entries(replacements)) {
  body = body.split(placeholder).join(value);
  subject = subject.split(placeholder).join(value);
}

return [{
  json: {
    trial_id: trial.id,
    to: trial.email,
    first_name: trial.first_name,
    subject: subject,
    body: body,
    brand_color: brandColor,
    email_type: trial.email_to_send,
    template_key: trial.template_key,
    skip: false
  }
}];

// Get data from the current item flowing through the pipeline
const trialData = $('Should Send Email?').item.json;
const emailType = trialData.email_to_send;
const trialId = trialData.id;

// Build the update object with the correct field
const updateField = `${emailType}_email_sent`;

return [{
  json: {
    id: trialId,
    update_field: updateField
  }
}];
